                    r2 = i; c2 = j;
                } else if (grid[i][j] == 'T') {
                    gr = i; gc = j;
                }
            }
        }

        // BFS over state (r1, c1, r2, c2)
        boolean[][][][] visited = new boolean[H][W][H][W];
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{r1, c1, r2, c2});
        visited[r1][c1][r2][c2] = true;

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int aR = state[0], aC = state[1];
            int bR = state[2], bC = state[3];

            // Check if both are at treasure
            if (aR == gr && aC == gc && bR == gr && bC == gc) {
                System.out.println("YES");
                return;
            }

            for (int dir = 0; dir < 4; dir++) {
                int naR = aR + dx[dir];
                int naC = aC + dy[dir];
                int nbR = bR + dx[dir];
                int nbC = bC + dy[dir];

                // Twin A movement
                if (naR < 0 || naR >= H || naC < 0 || naC >= W || grid[naR][naC] == '#') {
                    naR = aR;
                    naC = aC;
                }
                // Twin B movement
                if (nbR < 0 || nbR >= H || nbC < 0 || nbC >= W || grid[nbR][nbC] == '#') {
                    nbR = bR;
                    nbC = bC;
                }

                if (!visited[naR][naC][nbR][nbC]) {
                    visited[naR][naC][nbR][nbC] = true;
                    queue.add(new int[]{naR, naC, nbR, nbC});
                }
            }
        }

        System.out.println("NO");
    }
