public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int H, W;
    static char[][] grid;
    static int sr, sc, lr, lc, tr, tc;

    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};

    static boolean inside(int r, int c) {
        return 0 <= r && r < H && 0 <= c && c < W;
    }

    static boolean blocked(int r, int c) {
        return !inside(r, c) || grid[r][c] == '#';
    }

    static int encode(int r1, int c1, int r2, int c2) {
        return ((r1 * W + c1) * H + r2) * W + c2;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        H = fs.nextInt();
        W = fs.nextInt();
        grid = new char[H][W];

        for (int i = 0; i < H; i++) {
            String s = fs.next();
            for (int j = 0; j < W; j++) {
                grid[i][j] = s.charAt(j);
                if (grid[i][j] == 'R') {
                    sr = i; sc = j;
                    grid[i][j] = '.';
                } else if (grid[i][j] == 'L') {
                    lr = i; lc = j;
                    grid[i][j] = '.';
                } else if (grid[i][j] == 'T') {
                    tr = i; tc = j;
                    grid[i][j] = '.';
                }
            }
        }

        int totalStates = H * W * H * W;
        boolean[] vis = new boolean[totalStates];
        ArrayDeque<int[]> q = new ArrayDeque<>();

        int start = encode(sr, sc, lr, lc);
        vis[start] = true;
        q.add(new int[]{sr, sc, lr, lc});

        boolean ok = false;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r1 = cur[0], c1 = cur[1], r2 = cur[2], c2 = cur[3];

            if (r1 == tr && c1 == tc && r2 == tr && c2 == tc) {
                ok = true;
                break;
            }

            // If exactly one has already reached the target, this state is invalid:
            // the door would lock immediately.
            boolean firstAtTarget = (r1 == tr && c1 == tc);
            boolean secondAtTarget = (r2 == tr && c2 == tc);
            if (firstAtTarget ^ secondAtTarget) continue;

            for (int d = 0; d < 4; d++) {
                int nr1 = r1 + DR[d], nc1 = c1 + DC[d];
                if (blocked(nr1, nc1)) {
                    nr1 = r1; nc1 = c1;
                }

                int nr2 = r2 + DR[d], nc2 = c2 + DC[d];
                if (blocked(nr2, nc2)) {
                    nr2 = r2; nc2 = c2;
                }

                boolean aAt = (nr1 == tr && nc1 == tc);
                boolean bAt = (nr2 == tr && nc2 == tc);

                // If only one reaches target after this move, impossible from here.
                if (aAt ^ bAt) continue;

                int code = encode(nr1, nc1, nr2, nc2);
                if (!vis[code]) {
                    vis[code] = true;
                    q.add(new int[]{nr1, nc1, nr2, nc2});
                }
            }
        }

        System.out.println(ok ? "Yes" : "No");
    }
}

