int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> g(H);
    for (int i = 0; i < H; ++i) cin >> g[i];

    pair<int,int> A = {-1,-1}, B = {-1,-1}, G = {-1,-1};

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (g[i][j] == 'L') A = {i, j};
            else if (g[i][j] == 'R') B = {i, j};
            else if (g[i][j] == '%') G = {i, j};
        }
    }

    // If starts already at goal simultaneously.
    if (A == G && B == G) {
        cout << "Yes\n";
        return 0;
    }

    // visited[x1][y1][x2][y2]
    int N = H * W;
    vector<char> blocked(N, 0);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (g[i][j] == '#') blocked[i * W + j] = 1;
        }
    }

    auto inside = [&](int x, int y) {
        return 0 <= x && x < H && 0 <= y && y < W;
    };

    auto id = [&](int x1, int y1, int x2, int y2) -> long long {
        long long a = x1 * W + y1;
        long long b = x2 * W + y2;
        return a * N + b;
    };

    vector<char> vis((long long)N * N, 0);
    queue<State> q;

    vis[id(A.first, A.second, B.first, B.second)] = 1;
    q.push({A.first, A.second, B.first, B.second});

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (!q.empty()) {
        State cur = q.front();
        q.pop();

        for (int dir = 0; dir < 4; ++dir) {
            int nx1 = cur.x1 + dx[dir], ny1 = cur.y1 + dy[dir];
            if (!inside(nx1, ny1) || g[nx1][ny1] == '#') {
                nx1 = cur.x1;
                ny1 = cur.y1;
            }

            int nx2 = cur.x2 + dx[dir], ny2 = cur.y2 + dy[dir];
            if (!inside(nx2, ny2) || g[nx2][ny2] == '#') {
                nx2 = cur.x2;
                ny2 = cur.y2;
            }

            bool firstAtGoal = (nx1 == G.first && ny1 == G.second);
            bool secondAtGoal = (nx2 == G.first && ny2 == G.second);

            if (firstAtGoal && secondAtGoal) {
                cout << "Yes\n";
                return 0;
            }

            // If only one reaches the goal, the door locks, so this state is invalid.
            if (firstAtGoal ^ secondAtGoal) continue;

            long long h = id(nx1, ny1, nx2, ny2);
            if (!vis[h]) {
                vis[h] = 1;
                q.push({nx1, ny1, nx2, ny2});
            }
        }
    }

    cout << "No\n";
    return 0;
}

