int bfs(int r1, int c1, int r2, int c2, int dr1, int dc1, int dr2, int dc2) {
    // BFS
    int queue[MAXN*MAXN*MAXN*MAXN][4];
    int front = 0, back = 0;
    memset(visited, 0, sizeof(visited));
    visited[r1][c1][r2][c2] = 1;
    queue[back][0]=r1; queue[back][1]=c1; queue[back][2]=r2; queue[back][3]=c2;
    back++;
    while (front < back) {
        int cr1=queue[front][0], cc1=queue[front][1], cr2=queue[front][2], cc2=queue[front][3];
        front++;
        if (cr1==dr1 && cc1==dc1 && cr2==dr2 && cc2==dc2) return 1;
        for (int d = 0; d < 4; d++) {
            int nr1=cr1+dr[d], nc1=cc1+dc[d];
            int nr2=cr2+dr[d], nc2=cc2+dc[d];
            if (isWall(nr1,nc1)) { nr1=cr1; nc1=cc1; }
            if (isWall(nr2,nc2)) { nr2=cr2; nc2=cc2; }
            if (!visited[nr1][nc1][nr2][nc2]) {
                visited[nr1][nc1][nr2][nc2]=1;
                queue[back][0]=nr1; queue[back][1]=nc1; queue[back][2]=nr2; queue[back][3]=nc2;
                back++;
            }
        }
    }
    return 0;
}

