}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int x1, y1, x2, y2;
} State;

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char **g = (char **)malloc(H * sizeof(char *));
    for (int i = 0; i < H; i++) {
        g[i] = (char *)malloc((W + 1) * sizeof(char));
        scanf("%s", g[i]);
    }

    int sx1 = -1, sy1 = -1, sx2 = -1, sy2 = -1, tx = -1, ty = -1;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (g[i][j] == 'L') {
                if (sx1 == -1) {
                    sx1 = i; sy1 = j;
                } else {
                    sx2 = i; sy2 = j;
                }
            } else if (g[i][j] == '%') {
                tx = i; ty = j;
            }
        }
    }

    int total = H * W * H * W;
    unsigned char *vis = (unsigned char *)calloc(total, sizeof(unsigned char));
    State *q = (State *)malloc(total * sizeof(State));

    int front = 0, back = 0;
    int start_idx = ((sx1 * W + sy1) * H + sx2) * W + sy2;
    vis[start_idx] = 1;
    q[back++] = (State){sx1, sy1, sx2, sy2};

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (front < back) {
        State cur = q[front++];

        int at1 = (cur.x1 == tx && cur.y1 == ty);
        int at2 = (cur.x2 == tx && cur.y2 == ty);

        if (at1 && at2) {
            printf("Yes\n");
            free(vis);
            free(q);
            for (int i = 0; i < H; i++) free(g[i]);
            free(g);
            return 0;
        }

        if (at1 || at2) continue; /* one arrived earlier -> invalid */

        for (int dir = 0; dir < 4; dir++) {
            int nx1 = cur.x1 + dx[dir], ny1 = cur.y1 + dy[dir];
            int nx2 = cur.x2 + dx[dir], ny2 = cur.y2 + dy[dir];

            if (nx1 < 0 || nx1 >= H || ny1 < 0 || ny1 >= W || g[nx1][ny1] == '#') {
                nx1 = cur.x1; ny1 = cur.y1;
            }
            if (nx2 < 0 || nx2 >= H || ny2 < 0 || ny2 >= W || g[nx2][ny2] == '#') {
                nx2 = cur.x2; ny2 = cur.y2;
            }

            int n_at1 = (nx1 == tx && ny1 == ty);
            int n_at2 = (nx2 == tx && ny2 == ty);

            if (n_at1 ^ n_at2) continue; /* one reaches goal before the other */

            int idx = ((nx1 * W + ny1) * H + nx2) * W + ny2;
            if (!vis[idx]) {
                vis[idx] = 1;
                q[back++] = (State){nx1, ny1, nx2, ny2};
            }
        }
    }

    printf("No\n");

    free(vis);
    free(q);
    for (int i = 0; i < H; i++) free(g[i]);
    free(g);
    return 0;
}
